        'destination': r['destination'],
        'scheduled_departure_time_est': r['departure_time'],
        'scheduled_arrival_time_est': r['arrival_time'],
        'dates': cleaned_dates,
    }

resv_by_user = {}
reservations = {}
for r in conn.execute("SELECT * FROM flight_bookings WHERE source_skill=?", (SOURCE_SKILL,)):
